  "Earthquakes · Weather · Lightning · Pollen · Flights":
    "Землетрясения · Погода · Молнии · Пыльца · Рейсы",
  "Earthquakes, civil protection warnings, lightning, pollen, thermal comfort and flights overhead: for each one pick the sensor its integration already brought into Home Assistant. No field is required and each one is enough on its own: the page shows only the sources you have. The dashboard calls no service, it reads what is there.":
    "Землетрясения, предупреждения гражданской обороны, молнии, пыльца, тепловой комфорт и самолёты над домом: для каждого выберите датчик, который его интеграция уже принесла в Home Assistant. Ни одно поле не обязательно, и каждого достаточно самого по себе: страница показывает только те источники, что у вас есть. Панель не вызывает никаких служб, она читает то, что есть.",
  Eco: "Эко",
