  "Empty means the default shown in the field.":
    "Пусто — значит значение по умолчанию, показанное в поле.",
  "Empty means “on”. Without it the button still works: it simply does not stay lit.":
    "Пусто означает «on». Без него кнопка всё равно работает: просто не остаётся подсвеченной.",
