  "Engine (running/off)": "Двигатель (работает/выключен)",
  "Engine off": "Двигатель выключен",
  "Engine running": "Двигатель работает",
  "Enough on its own: on and off, no numbers.":
    "Его одного достаточно: включён и выключен, без цифр.",
  "Enough on its own: the card says on and off, and does not pretend to know the degrees.":
    "Хватит и его одного: карточка скажет «включён» и «выключен» и не станет выдумывать градусы.",
  "Enter a label.": "Введите подпись.",
  "Enter a load name": "Введите название нагрузки",
