  "Enter a name and a valid entity (e.g. light.living or switch.kitchen)":
    "Впишите название и правильную сущность (например, light.living или switch.kitchen)",
  "Enter a name and a valid entity.": "Введите имя и корректную сущность.",
  "Enter a name and at least one entity": "Впишите название и хотя бы одну сущность",
  "Enter a name and at least one entity: a cover.* or switch.* among shutter, curtain and awning, or the opening sensor alone.":
    "Укажите название и хотя бы одну сущность: cover.* или switch.* среди ставней, штор и маркизы — либо только датчик открытия.",
  "Enter a name and camera entity": "Впишите название и сущность камеры",
