  "Entities in alert groups": "Сущности в группах оповещений",
  Entity: "Сущность",
  "Entity links": "Связи сущностей",
  "Entity to control": "Сущность для управления",
  "Entity to control, e.g. switch.luce_salone": "Сущность для управления, напр. switch.luce_salone",
  "Entity unavailable in Home Assistant.": "Сущность недоступна в Home Assistant.",
  Entrance: "Прихожая",
  "Equal to…": "Равно…",
  "Equal to… (manual state)": "Равно… (состояние вручную)",
  Error: "Ошибка",
  "Estimated time": "Расчётное время",
  Events: "События",
  "Every area is a Home Assistant panel of its own, with its own arming modes. The one marked “on the page now” is what the dial and the keypad are commanding: the eye beside another one brings it on screen in its place.":
    "Каждая зона — это отдельная панель Home Assistant со своими режимами постановки. Та, что помечена «сейчас на странице», — это та, которой управляют циферблат и клавиатура: глаз рядом с другой выводит её на экран вместо неё.",
  "Every field is optional: the card automatically shows what is available. Start, duration, energy and cost of the last cycle are computed automatically from power transitions unless you provide dedicated entities.":
    "Все поля необязательны: карточка сама показывает то, что доступно. Начало, длительность, энергия и стоимость последнего цикла считаются автоматически по изменениям мощности, если вы не укажете отдельные сущности.",
  "Every filled box must be a cover.* or switch.* entity.":
    "В каждом заполненном поле должна быть сущность cover.* или switch.*.",
  "Every load below is a circle of the Energy flow, under Home, in the order of this list. What you write here is what the flow shows, and the devices you file under it are the ones that appear when you tap the circle.":
    "Каждая нагрузка ниже — это круг потока «Энергия» под «Домом», в порядке этого списка. Что вы напишете здесь, то и покажет поток, а приборы, отнесённые к ней, появятся при нажатии на круг.",
  "Every plant has its own meter, its own solar, its own battery and its own loads. The fields below belong to the selected plant: adding one starts from scratch and leaves what you already configured alone.":
    "У каждого объекта свой счётчик, своя солнечная станция, свой накопитель и свои нагрузки. Поля ниже относятся к выбранному объекту: добавление нового начинается с нуля и не трогает уже настроенное.",
  "Every plant has its own thirteen fields. The one marked “on the page now” is what the Solar thermal page and the Home tile are showing: the eye beside another one brings it on screen in its place.":
    "У каждой установки свои тринадцать полей. Та, что помечена «сейчас на странице», — это то, что показывают страница «Солнечный коллектор» и плитка на главной: глаз рядом с другой выводит её на экран вместо неё.",
  "Everything is here: the window's card shows its room's humidity and says to open as soon as it goes above the threshold.":
    "Всё на месте: карточка окна показывает влажность своей комнаты и советует открыть, как только она превысит порог.",
  "Everything off": "Всё выключено",
  "Everything on the repository": "Всё, что есть в репозитории",
  "Everything the dashboard can do, and whether it shows. The same switch is also at the top of each section's own tab: here they are all together, so you can see what exists without opening them one by one.":
    "Всё, что умеет панель, и видно ли это. Тот же переключатель есть и вверху вкладки каждого раздела: здесь они собраны вместе, чтобы увидеть, что есть, не открывая их по одному.",
  "Exact colour": "Точный цвет",
