  Glasses: "Очки",
  "Go ahead and write: on the other side there is a person, not a form.":
    "Пишите спокойно: на той стороне человек, а не форма.",
  Good: "Хороший",
  "Good up to the first, fair up to the second, poor up to the third, bad beyond. The defaults are the norms: the European index bands for particulates and gases, EN 16798-1 for CO₂, the WHO guidelines for monoxide. Change them only if you know why.":
    "Хорошо до первого, приемлемо до второго, плохо до третьего, очень плохо выше. По умолчанию это нормы: диапазоны европейского индекса для частиц и газов, EN 16798-1 для CO₂, рекомендации ВОЗ для монооксида. Меняйте, только если знаете зачем.",
  Graphite: "Графит",
  Grass: "Травы",
  "Grass (optional)": "Травы (необязательно)",
  Grate: "Решётка",
  "Grate and window open": "Решётка и окно открыты",
  "Grate contact sensor": "Датчик открытия решётки",
  "Grate open": "Решётка открыта",
  Gray: "Седой",
  "Great discomfort": "Сильный дискомфорт",
  "Greater than…": "Больше чем…",
