  "Grid view": "Вид сеткой",
  Grill: "Гриль",
  Groceries: "Покупки",
  "Ground Floor": "Первый этаж",
  "Ground floor robot": "Робот первого этажа",
  Group: "Группа",
  "Group created — now add loads below": "Группа создана — теперь добавьте нагрузки ниже",
  "Group deleted": "Группа удалена",
  "Group icon": "Значок группы",
  "Group name": "Имя группы",
  "Groups are the popup opened from a flow circle. Their children are the cards shown inside, such as Oven, Fridge or Dishwasher.":
    "Группа — это окно, открывающееся из круга потока. Её вложенные элементы — карточки внутри, например Духовка, Холодильник или Посудомоечная машина.",
  Guard: "Охранник",
  "Guest room": "Гостевая комната",
  Gym: "Спортзал",
  "HA WebSocket not active": "WebSocket HA неактивен",
  'HA entities. Leave empty to keep the default reference (if it does not exist in your HA, the card shows "—").':
    'сущности HA. Оставьте пустым, чтобы сохранить ссылку по умолчанию (если её нет в вашем HA, карточка покажет "—").',
  "HA entity (autocomplete enabled). You can skip this step and finish later from":
    "сущность HA (с автодополнением). Этот шаг можно пропустить и закончить позже в",
