  On: "Включено",
  "On / Active / Open (on)": "Включено / Активно / Открыто (on)",
  "On Home": "На главной",
  "On battery": "От батареи",
  "On battery · ${carica}%": "От батареи · ${carica} %",
  "On cards show the room temperature big (target below)":
    "На карточках показывать крупно температуру в комнате (цель ниже)",
  "On mains": "От сети",
  "On time": "По расписанию",
  "On which page": "На какой странице",
  "On, the radar plays the last hour of rain: you see which way the front is moving, not only where it is now. That is six frames instead of one, so six rounds of tiles: turn it off on a slow connection, or if you prefer a single image.":
    "Включённый радар проигрывает последний час дождя: видно, куда идёт фронт, а не только где он сейчас. Это шесть кадров вместо одного, то есть шесть загрузок плиток: выключите при медленном соединении или если хватает одной картинки.",
  "On/off control": "Управление вкл./выкл.",
  "On/off · Brightness · Colour": "Вкл./выкл. · Яркость · Цвет",
  "On/off · Consumption · Room by room": "Вкл/выкл · Потребление · Комната за комнатой",
  "One bin per material, and for each the sensor that says when the collection comes: the page answers the evening question — what do I put out tonight — and the Home tile lights up the day before. Whoever has a single calendar, with one event per collection, puts it in the box at the bottom.":
    "Один бак на фракцию, и для каждого датчик, который говорит, когда приедет вывоз: страница отвечает на вечерний вопрос — что выставить сегодня — а плитка на главной загорается накануне. У кого один календарь с одним событием на вывоз, вписывает его в поле внизу.",
  "One room at a time · Scenes · Sensors": "По одной комнате · Сцены · Датчики",
  "One single tile": "Одна общая плитка",
  "One step, and you will never be asked again: open github.com/login/device and type this code.":
    "Один шаг, и больше об этом не спросят: откройте github.com/login/device и введите этот код.",
  "One tile per plant": "По одной на установку",
  "One window can carry all three: fill in the boxes you have, the box tells the type.":
    "На одном окне могут быть все три: заполните те поля, что у вас есть, — поле само задаёт тип.",
  "Only daily sensors or Recorder deltas from cumulative total meters are counted. Lifetime values are never added directly.":
    "Учитываются только суточные датчики или разности Recorder по накопительным счётчикам. Накопленные значения никогда не складываются напрямую.",
  "Only if you already have a helper measuring the period. Without one, the period comes from the total meter.":
    "Только если у вас уже есть helper, измеряющий период. Без него период берётся из суммарного счётчика.",
  "Only needed when the shutter is driven by two relays — one that sends it up, one that sends it down — like a Shelly left in switch mode: then “Close” switches this one on, and “Stop” switches both off. With a real cover.* leave it empty.":
    "Нужно только тогда, когда рольставней управляют два реле — одно поднимает, другое опускает, как у Shelly, оставленного в режиме выключателя: тогда «Закрыть» включает это реле, а «Стоп» выключает оба. С настоящей cover.* оставьте поле пустым.",
  "Only rooms containing a light are shown. Edit opens all light fields, not a browser prompt. The pills say what each light can do — RGB, tunable white, dimmer or plain on/off — and that is what drives the controls in the popup.":
    "Показываются только комнаты со светильником. «Изменить» открывает все поля светильника, а не окно браузера. Метки говорят, что умеет каждый светильник — RGB, регулируемый белый, диммер или простое вкл./выкл. — и именно это определяет органы управления в окне.",
  "Only the modes the panel actually accepts are listed. Removing one hides it from the section and changes nothing about what the panel can do; disarm always stays.":
    "Здесь только те режимы, которые панель действительно принимает. Убрать один — значит скрыть его в разделе; на возможности панели это не влияет, а снятие с охраны остаётся всегда.",
  "Only with the soil below (%)": "Только если почва ниже (%)",
  Open: "Открыта",
  "Open (as before)": "Открыть (как раньше)",
  "Open the menu": "Открыть меню",
