    "⚪ Пустой раздел — добавьте ниже сущность, чтобы показать его",
  "You haven't saved": "Вы не сохранили",
  "You entered entities in this section without saving them. If you leave now, they will be lost.":
    "Вы добавили сущности в этот раздел, но не сохранили их. Если уйти сейчас, они будут потеряны.",
  "Save and continue": "Сохранить и продолжить",
  "Leave without saving": "Выйти без сохранения",
  "Stay here": "Остаться",
  "Nobody home": "Никого нет дома",
  "Big buttons: a dashboard action or any entity (a scene, a script, a button). For each one the name on the tablet, the line below and the drawing.":
    "Большие кнопки: действие панели или любая сущность (сцена, скрипт, кнопка). Для каждой — название на планшете, строка снизу и рисунок.",
  "Full config": "Вся настройка",
  "On, a light added to the room in the source dashboard shows up by itself. Off, the slots are chosen here: any entity or action, with the name and drawing you want.":
    "Включено: свет, добавленный в комнату на исходной панели, появится сам. Выключено: места выбираются здесь — любая сущность или действие, с нужным названием и рисунком.",
  "Slots of your own: in each one any Home Assistant entity — a light, a socket, a lock, a sensor — or a dashboard action, with the name and drawing you want.":
    "Только ваши места: в каждом любая сущность Home Assistant — свет, розетка, замок, датчик — или действие панели, с нужным названием и рисунком.",
  "A dehumidifier is not a thermostat: pick its humidifier entity and the Climate page gives it a card of its own, with the current humidity, the target, the modes, the fan and the tank-full warning. The other fields fill themselves in when you save.":
    "Осушитель — это не термостат: выберите его сущность humidifier, и страница «Климат» даст ему собственную карточку с текущей влажностью, целью, режимами, вентилятором и предупреждением о полном баке. Остальные поля заполнятся сами при сохранении.",
