    "Выберите существующую комнату и свяжите с ней датчики температуры и влажности. При правке датчики можно перенести в другую комнату. Имя и значок комнаты меняются в разделе «Комнаты».",
  "Select and order Report entries without changing dashboard order.":
    "Выберите и упорядочьте строки отчёта, не меняя порядок на панели.",
