  "Shutter open": "Рольставня открыта",
  "Shutter opening": "Рольставня открывается",
  Shutters: "Рольставни",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "Рольставни и шторы появляются на странице 🪟 Окна, сгруппированные по этажу и комнате. Каждая строка принимает сущность cover.* — с положением и процентами — или реле switch.*: одно, если при включении рольставня остаётся поднятой, и два, если одно поднимает, а другое опускает, как Shelly в режиме выключателя. Если окно открывается вручную — ставни, жалюзи, ручка — оставь поля команд пустыми и заполни только датчик открытия: карточка всё равно нарисуется и скажет, открыто ли оно.",
  "Shutters · Curtains · Contact sensors": "Рольставни · Шторы · Датчики открытия",
  "Sign path timeout": "Время подписи пути вышло",
  "Simple alternative to the duration entity.": "Простая альтернатива сущности длительности.",
  "Since last charge": "С последней зарядки",
  "Since last restart": "С последнего перезапуска",
  Singer: "Певец",
  "Single calendar or sensor (optional)": "Один календарь или датчик (необязательно)",
  "Skin tone": "Тон кожи",
  "Skip detection →": "Пропустить поиск →",
  "Skip the program if ≥ (%)": "Пропустить программу при ≥ (%)",
  Slate: "Сланец",
  "Slight discomfort": "Лёгкий дискомфорт",
  "Slightly cool": "Слегка прохладно",
  "Slightly warm": "Слегка тепло",
  "Small pool": "Небольшой бассейн",
  "Smart thermostats publish the heating mode on a separate entity: TADO has Home and Away, others add Holiday or Boost. The card shows it, and if the entity is a select or an input_select you can change it right there.":
    "Умные термостаты публикуют режим отопления в отдельной сущности: у TADO это Дома и Не дома, у других добавляются Отпуск или Boost. Карточка его показывает, а если сущность — select или input_select, режим можно сменить прямо там.",
  "SmartThings, Sonos, Chromecast, AirPlay… pick the device and the player arrives ready-made: its entity, the controls the integration publishes next to it — a TV's power switch, the input dropdown — and its readings. Or, below, one field at a time.":
    "SmartThings, Sonos, Chromecast, AirPlay… выберите устройство, и проигрыватель придёт готовым: его сущность, кнопки рядом — выключатель телевизора, список источников — и его показания. Или ниже, поле за полем.",
  Smoke: "Дым",
  "Smoke & gas detectors": "Датчики дыма и газа",
  "Smoke / Air": "Дым / воздух",
  "Smoke and gas": "Дым и газ",
  Soak: "Замачивание",
  Socket: "Розетка",
  "Socket power (W) — above 5 W the washer counts as running":
    "Мощность розетки (Вт) — выше 5 Вт стиральная машина считается работающей",
