  "Tap a room: each unit starts with its own steps":
    "Коснитесь комнаты: каждый блок включается своими шагами",
  "Tap a sensor": "Нажмите на датчик",
  "Tap an appliance to open its card.": "Нажмите на прибор, чтобы открыть его карточку.",
  "Tap the fan": "Нажмите на вентилятор",
  "Tap to change the mode": "Нажмите, чтобы сменить режим",
