  "${nome}: the arrows, OK and the other keys show under the card while the TV is on.":
    "${nome}: стрелки, OK и остальные кнопки появляются под карточкой, пока телевизор включён.",
  "A remote.* entity is required.": "Нужна сущность remote.*.",
