  "Previous channel": "Предыдущий канал",
  "Remote control": "Пульт",
  "TV home screen": "Главный экран телевизора",
  "TV menu": "Меню телевизора",
  "The TV's arrows, OK, back, home screen and channels, under its card and only while the TV is on. It needs the TV's remote.* entity: Samsung (Samsung Smart TV integration), Sony Bravia, Philips, Android TV and Google TV, Apple TV, Roku. LG webOS TVs don't need it.":
    "Стрелки, OK, назад, главный экран и каналы телевизора — под его карточкой и только когда он включён. Нужна сущность remote.* телевизора: Samsung (интеграция Samsung Smart TV), Sony Bravia, Philips, Android TV и Google TV, Apple TV, Roku. Телевизорам LG webOS она не нужна.",
  "These are in the house — one tap picks it:": "Вот что есть в доме — одно касание выбирает:",
  "Volume down": "Тише",
  "Volume up": "Громче",
  "${quante} actions": "Действий: ${quante}",
  "${quante} areas together: the buttons apply to all":
    "Зон вместе: ${quante} — кнопки действуют на все",
  "Press and hold an area to pick more than one": "Удерживайте зону, чтобы выбрать несколько",
  "1 action": "1 действие",
  "Close the ${nome} group": "Свернуть группу «${nome}»",
  "Open the ${nome} group": "Развернуть группу «${nome}»",
  "The group is optional: actions with the same group sit together on Home, under a title that says how many are on and closes with a tap. Without groups it stays a single row.":
    "Группа необязательна: действия с одной группой стоят вместе на главной, под заголовком, который показывает, сколько включено, и сворачивается одним касанием. Без групп остаётся один ряд.",
  "e.g. Lights, Shutters": "напр. Свет, Жалюзи",
  "💾 Group saved": "💾 Группа сохранена",
  "1 open · tap to close": "1 открыта · нажмите, чтобы закрыть",
  "open · tap to close": "открыто · нажмите, чтобы закрыть",
  "1 open now · closed by hand": "1 открыто сейчас · закрывается вручную",
  "open now · closed by hand": "открыто сейчас · закрываются вручную",
  "1 unlocked · tap to lock": "1 отперт · нажмите, чтобы запереть",
  "unlocked · tap to lock": "отперто · нажмите, чтобы запереть",
  "Door or window": "Дверь или окно",
  Doors: "Двери",
  Locks: "Замки",
  "lock unlocked": "замок отперт",
  "locks unlocked": "замки отперты",
  "shutter open": "рольставня открыта",
  "shutters open": "рольставни открыты",
  "Under the weather, open doors and open windows are two pills. By default the class Home Assistant gives the contact decides; pick here when it is not the right one.":
    "Под погодой открытые двери и открытые окна — две разные плашки. По умолчанию решает класс, который Home Assistant даёт датчику; выберите здесь, если он неверный.",
  "If the camera already has its own integration in Home Assistant — Reolink, Tapo, Hikvision — the entity is already there: pick it in the field above, and the video goes through it.":
    "Если у камеры уже есть своя интеграция в Home Assistant — Reolink, Tapo, Hikvision, — сущность уже есть: выберите её в поле выше, и видео пойдёт через неё.",
  "The stream name only works with the dashboard opened outside Home Assistant: in here it cannot be reached, and the camera goes through its entity.":
    "Имя потока работает только тогда, когда панель открыта вне Home Assistant: отсюда до него не добраться, и камера идёт через свою сущность.",
  "HLS: skipped, Home Assistant declares no stream for this camera":
    "HLS: пропущено, Home Assistant не объявляет поток для этой камеры",
  "WebRTC: the go2rtc stream name only works with the dashboard opened outside Home Assistant — in here the camera goes through its entity":
    "WebRTC: имя потока go2rtc работает только при панели, открытой вне Home Assistant — здесь камера идёт через свою сущность",
  "WebRTC: tried first with its full time, the video did not arrive":
    "WebRTC: сначала опробовано со всем отведённым временем, видео не пришло",
  Bypass: "Обойти",
  "Bypass from the alarm?": "Исключить из охраны?",
  "Bypassed from the alarm": "Исключена из охраны",
  "Found automatically, this one is used:": "Найден автоматически, используется этот:",
  "Re-include": "Вернуть под охрану",
  "The alarm panel refused": "Панель отказала",
  "${cifre(come.energiaKwh, 1)} of ${cifre(come.capacitaKwh, 1)} kWh":
    "${cifre(come.energiaKwh, 1)} из ${cifre(come.capacitaKwh, 1)} кВт·ч",
  "${giorni} days": "${giorni} дн.",
