  "on the tablet": "на планшете",
  "or an action": "или действие",
  "Second button name": "Название второй кнопки",
  "The page takes its temperature and suggested controls from here":
    "Отсюда страница берёт температуру и предлагаемые элементы управления",
  "Your own controls": "Ваши элементы управления",
  "Heating · Cooling": "Обогрев · Охлаждение",
  "It fills itself with the source dashboard's climate, split into the Cooling and Heating tabs like the Climate section: air conditioners in cooling, radiators and thermostats in heating, heat pumps in both.":
    "Заполняется сама климатом исходной панели, разделённым на вкладки Охлаждение и Обогрев, как в разделе Климат: кондиционеры в охлаждении, радиаторы и термостаты в обогреве, тепловые насосы в обеих.",
  "Opens on": "Открывается на",
  "Page type": "Тип страницы",
  "Shown on the tab at the top": "Показывается на вкладке сверху",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "Панель настенного планшета. Выберите страницы — вкладки сверху — и что будет на каждой. На планшете, удерживая часы две секунды, вы вернётесь сюда.",
  "All blinds": "Все жалюзи",
  "At the top and on the rest screen. Empty: the first one Home Assistant has":
    "Сверху и на экране покоя. Пусто: первая, что есть в Home Assistant",
