  "House consumption": "Потребление дома",
  "House uses": "Дом потребляет",
  "How many cards on screen; the rest scroll":
    "Сколько карточек на экране; остальные прокручиваются",
  "How many slots, and how big. In portrait columns and rows swap":
    "Сколько мест и какого размера. В портретной ориентации столбцы и строки меняются местами",
  "It fills itself with every blind of the source dashboard: up, stop and down for each one.":
    "Заполняется сама всеми жалюзи исходной панели: вверх, стоп и вниз для каждой.",
  "Lights off": "Свет выключен",
  "Like the page type": "Как тип страницы",
  "Live pictures": "Живое изображение",
  "Live preview": "Живой предпросмотр",
  "No camera in the dashboard": "Нет камер в панели",
  "No room with sensors or lights": "Нет комнат с датчиками или светом",
  "Of the tab and the title": "Вкладки и заголовка",
  "Off, the tablet stays on the page it was on": "Выкл.: планшет остаётся на той странице, где был",
  "On rest go back to the first page": "В режиме покоя возвращаться на первую страницу",
  "One tile per room, with temperature, humidity and how many lights are on, live. Rooms and their sensors come from the source dashboard.":
    "Одна плитка на комнату: температура, влажность и сколько света включено, в реальном времени. Комнаты и их датчики берутся из исходной панели.",
  "Positive is drawn, negative is fed in": "Положительное — потребление, отрицательное — отдача",
  "Power, in W or kW": "Мощность, в Вт или кВт",
  "Right now, at home": "Прямо сейчас, дома",
  "Solar makes": "Солнце даёт",
  "Solar production": "Солнечная выработка",
  "Temperature · Humidity · Lights": "Температура · Влажность · Свет",
  "Temperature on the rest screen": "Температура на экране покоя",
  "The source dashboard's cameras, all together; a tap opens one full screen.":
    "Камеры исходной панели, все вместе; касание открывает одну на весь экран.",
  "To the grid": "В сеть",
  "Unsaved changes: the tablet sees them after «Save».":
    "Несохранённые изменения: планшет увидит их после «Сохранить».",
  "Empty: the ones from the dashboard's Music section": "Пусто: те, что в разделе «Музыка» панели",
  "No player: add them in the Music section or here in the config":
    "Нет плееров: добавьте их в разделе «Музыка» или здесь в настройках",
  Players: "Плееры",
  "The ones chosen here, in this order": "Выбранные здесь, в этом порядке",
  "The player that's playing, big, with cover, buttons, volume and sources; beside it the others, each with its own play. A tap on a player brings it up big.":
    "Играющий плеер — крупно, с обложкой, кнопками, громкостью и источниками; рядом остальные, у каждого своя кнопка воспроизведения. Касание плеера выводит его крупно.",
