  "Start ${a.name} on solar": "Запусти ${a.name} от солнца",
  "Take out: ${r.name}": "Вынести: ${r.name}",
  "The alarm has been triggered.": "Сработала сигнализация.",
  "The alarm is going off": "Сигнализация звенит",
  "the car": "машину",
  "The house assistant watches the house for you and tells you the most important thing to do right now: lights left on in an empty house, a window open with the heating on, rain on its way, the laundry done, spare solar power. It learns from what you dismiss, and remembers it for the whole household. On a computer or tablet it sits to the right of the people, on a phone below them.":
    "Домашний помощник следит за домом вместо тебя и говорит, что сейчас важнее всего: свет в пустом доме, открытое окно при включённом отоплении, приближающийся дождь, готовая стирка, лишняя солнечная энергия. Он учится на том, что ты отклоняешь, и помнит это для всей семьи. На компьютере и планшете он справа от людей, на телефоне — под ними.",
  "The house is drawing ${kw} kW from the grid": "Дом берёт из сети ${kw} кВт",
  "The house is empty and ${nomi(aperte, l)} is unlocked":
    "Дом пуст, а ${nomi(aperte, l)} не заперта",
  "The leak sensor is wet: shall I close the valve?": "Датчик протечки мокрый: перекрыть кран?",
  "The leak sensor is wet.": "Датчик протечки мокрый.",
  "There are ${quanti} updates to install": "Обновлений для установки: ${quanti}",
  "There is an update to install": "Есть обновление для установки",
  Tonight: "Вечером",
  "Turn it off until someone is back?": "Выключить, пока кто-нибудь не вернётся?",
  "Turn it off?": "Выключить?",
  "Turn off climate": "Выключить климат",
  "Turn them off?": "Выключить их?",
  urgent: "срочно",
  "Water detected: ${nomi(bagnati, l)}": "Обнаружена вода: ${nomi(bagnati, l)}",
  "What it talks about": "О чём он говорит",
  "Worth a check.": "Стоит проверить.",
  "You left with ${nomi(aperte, l)} open": "Вы ушли, а ${nomi(aperte, l)} открыто",
  "You're near the limit: can ${nomi(accesi, l)} wait?":
    "Ты близко к пределу: ${nomi(accesi, l)} может подождать?",
  "You're near the meter's limit.": "Ты близко к пределу счётчика.",
  "You're out and ${g.name} is open": "Вас нет дома, а ${g.name} открыт",
  "e.g. 30": "напр. 30",
  "End-of-cycle delay under ${minuti} minutes: 0 W pauses mid-programme look like the end of the cycle.":
    "Задержка конца цикла меньше ${minuti} минут: паузы 0 Вт посреди программы выглядят как конец цикла.",
  "Recommended: running ${a} W, standby ${b} W, delay ${minuti} min.":
    "Рекомендуется: работа ${a} Вт, ожидание ${b} Вт, задержка ${minuti} мин.",
  "Running threshold under 1 W: a lit display is enough to show Running.":
    "Порог работы меньше 1 Вт: достаточно горящего дисплея, чтобы показать «Работает».",
  "Standby threshold at or above the running one: standby can never show.":
    "Порог ожидания равен порогу работы или выше: режим ожидания никогда не появится.",
  "Use the recommended values": "Использовать рекомендуемые значения",
  "With these values one cycle can turn into many mini-cycles.":
    "С этими значениями один цикл может превратиться во множество мини-циклов.",
  "System off": "Система выключена",
  "Battery power": "Мощность батареи",
  "Battery: charge": "Батарея: заряд",
  "Battery: power": "Батарея: мощность",
  "Big live numbers. Left empty, they come from the source dashboard's Energy section, with its direction.":
    "Крупные цифры в реальном времени. Если пусто, берутся из раздела «Энергия» исходной панели, с её направлением.",
  "Charging power": "Мощность заряда",
  "Discharging power": "Мощность разряда",
