  "otherwise → ${cosa}": "иначе → ${cosa}",
  "PREMIUM · COMING SOON": "PREMIUM · СКОРО",
  "Premium comes with the apps": "Premium придёт с приложениями",
  "Premium is bought": "Premium покупается",
