  "SAVING…": "СОХРАНЯЮ…",
  "Search an automation…": "Найти автоматизацию…",
  "See ›": "Смотреть ›",
  "See all the home's automations, turn them on and off, create new ones in three steps and get suggestions designed for your home.": "Смотрите все автоматизации дома, включайте и выключайте их, создавайте новые в три шага и получайте предложения для вашего дома.",
  "stopped for now": "пока остановлены",
  "Suggestions designed for your home": "Предложения для вашего дома",
  "the ${evento} event arrives": "приходит событие ${evento}",
  "the home did not answer": "дом не ответил",
  "The home that does it by itself: lights, climate, shutters and alerts that start when needed.": "Дом, который всё делает сам: свет, климат, жалюзи и уведомления, которые срабатывают, когда нужно.",
  "The home's automations": "Автоматизации дома",
  "The list and saving go through the GdAHome add-on: it is not here.": "Список и сохранение работают через дополнение GdAHome: здесь его нет.",
  "the new automation": "новая автоматизация",
  "then → ${allora}": "тогда → ${allora}",
  "This automation lives in a Home Assistant file: here you turn it on, off and run it, and it is changed there.": "Эта автоматизация находится в файле Home Assistant: здесь вы её включаете, выключаете и запускаете, а изменяется она там.",
  "This automation uses advanced features (a choice between cases, a template, a blueprint…): here you can turn it on and off, run it, rename it and change its room. For the rest:": "Эта автоматизация использует расширенные функции (выбор вариантов, шаблон, blueprint…): здесь её можно включить, выключить, запустить, переименовать и сменить комнату. Остальное:",
  "Turn ${v.nome} on or off": "Включить или выключить ${v.nome}",
  "Turn them on and off with a tap": "Включайте и выключайте их одним касанием",
  "wait ${min} min": "подождать ${min} мин",
  "waits a while": "немного ждёт",
  "waits for something to happen": "ждёт, пока что-то произойдёт",
  "When the apps are in the stores, you turn on Premium from the app and Automations unlock here by themselves.": "Когда приложения появятся в магазинах, вы включите Premium в приложении, и здесь Автоматизации откроются сами.",
  "You'll find it in Settings → Automations, labelled GdAHome.": "Вы найдёте её в Настройки → Автоматизации, с меткой GdAHome.",
  "You'll find it there and Home Assistant runs it.": "Вы найдёте её там, и её выполняет Home Assistant.",
  "🚨 Removed": "🚨 Удалено",
  "🚨 Saved: the house knows when it goes off": "🚨 Сохранено: дом знает, когда срабатывает тревога",
  "A sensor that names the zone. Empty: the house looks at which door, window or motion turned on last.": "Датчик, называющий зону. Пусто: дом смотрит, какая дверь, окно или движение сработали последними.",
  "at rest": "в покое",
  "Empty means “on”.": "Пусто означает «on».",
  "For the “Siren off” button in the notification and in Security.": "Для кнопки «Выключить сирену» в уведомлении и в разделе «Безопасность».",
  "NEW": "НОВОЕ",
  "Siren (optional)": "Сирена (необязательно)",
  "siren off": "сирена выключена",
  "Siren off": "Выключить сирену",
  "siren on": "сирена включена",
  "Siren on": "Сирена включена",
  "The entity that says the alarm is going off: a switch, a sensor or a helper. When it reads “triggered” Security, the Home tile and the wall panel turn red, and the house sends the urgent notification.": "Сущность, сообщающая, что сработала тревога: выключатель, датчик или помощник. Когда она в состоянии «сработала», раздел «Безопасность», плитка главной страницы и настенная панель становятся красными, а дом отправляет срочное уведомление.",
  "The value that means “triggered”": "Значение, означающее «сработала»",
  "What set it off (optional)": "Что её вызвало (необязательно)",
  "When it is triggered": "Когда сработала",
  "Where to read if it is triggered": "Где смотреть, сработала ли она",
  "zone": "зона",
  "appliance without a plant": "прибор без установки",
  "appliances without a plant": "приборы без установки",
  "assign them": "назначь их",
  "Automatic circles from rooms": "Автоматические круги из комнат",
  "Confirm the suggestions": "Подтвердить предложения",
  "Each plant has its own meter and its own limit: above the threshold the alert says which plant. The one you had before now belongs to the first plant.": "У каждой установки свой счётчик и свой лимит: выше порога оповещение называет установку. Прежний порог теперь принадлежит первой установке.",
  "Group by floor": "Группировать по этажам",
  "no plant": "нет установки",
  "One circle per floor; tap it to see its rooms.": "Один круг на этаж; нажми, чтобы увидеть комнаты.",
  "Power threshold · one per meter": "Порог мощности · по одному на счётчик",
  "suggested: its floor is covered by": "предложено: его этаж покрывает",
  "suggested: the same power is already a load of": "предложено: та же мощность уже нагрузка в",
  "The house appliances become per-room circles in the flow. Each one goes in its meter's flow: until you say which, it shows up in none.": "Приборы дома становятся в потоке кругами по комнатам. Каждый идёт в поток своего счётчика: пока не укажешь, он не появится ни в одном.",
  "The meter that measures it: it shows up in that plant's flow.": "Счётчик, который его измеряет: прибор появится в потоке этой установки.",
  "The rooms have no floor: you can set one in the Rooms page of the config.": "У комнат нет этажа: его можно задать на странице «Комнаты» в настройках.",
  "The rooms on the chosen floors go to this plant by themselves, with their appliances.": "Комнаты выбранных этажей сами относятся к этой установке, вместе с приборами.",
  "This plant's rooms, with their appliances; the rest under «Other».": "Комнаты этой установки с их приборами; остальное в «Другое».",
  "to confirm": "подтвердить",
  "To decide": "Не выбрано",
  "What the ${quale} meter measures": "Что измеряет счётчик ${quale}",
